import struct, hashlib, base64
from pathlib import Path
data = open('/tmp/zeroomega.crx','rb').read()
ver, header_size = struct.unpack('<II', data[4:12])
header = data[12:12+header_size]
alphabet='abcdefghijklmnop'
target='pfnededegaaopdmhkdmcofjmoldfiped'

def extid_of(key: bytes) -> str:
  h=hashlib.sha256(key).digest()[:16]
  return ''.join(alphabet[b>>4]+alphabet[b&0xf] for b in h)

# Brute: every ASN.1 SEQUENCE in header
matches=[]
for i in range(len(header)-4):
  if header[i] != 0x30: continue
  # try definite long form 3082
  if header[i+1]==0x82:
    ln=header[i+2]*256+header[i+3]
    total=4+ln
  elif header[i+1]==0x81:
    ln=header[i+2]; total=3+ln
  elif header[i+1]<0x80:
    ln=header[i+1]; total=2+ln
  else:
    continue
  if total<50 or i+total>len(header):
    continue
  key=header[i:i+total]
  eid=extid_of(key)
  if eid==target:
    print('FOUND at', i, 'len', total)
    Path('/tmp/zeroomega_pubkey.b64').write_text(base64.b64encode(key).decode())
    matches.append(key)
    break
  # also try if key is just the bit string contents etc
print('matches', len(matches))

# Parse CRX3 protobuf manually: CrxFileHeader
# message CrxFileHeader {
#  repeated AsymmetricKeyProof sha256_with_rsa = 2;
#  repeated AsymmetricKeyProof sha256_with_ecdsa = 3;
#  optional bytes signed_header_data = 10000;
# }
# message AsymmetricKeyProof {
#  optional bytes public_key = 1;
#  optional bytes signature = 2;
# }

def read_varint(buf, i):
  x=0; s=0
  while True:
    b=buf[i]; i+=1
    x |= (b & 0x7f) << s
    if not (b & 0x80): return x, i
    s += 7

def parse_protobuf_bytes_fields(buf):
  i=0
  fields=[]
  while i < len(buf):
    key, i = read_varint(buf, i)
    fn, wt = key>>3, key&7
    if wt==2: # len-delimited
      ln, i = read_varint(buf, i)
      val=buf[i:i+ln]; i+=ln
      fields.append((fn,val))
    elif wt==0:
      val, i = read_varint(buf, i)
      fields.append((fn,val))
    else:
      print('unknown wt', wt, 'at', i); break
  return fields

fields=parse_protobuf_bytes_fields(header)
print('top fields', [(fn, len(v) if isinstance(v, (bytes,bytearray)) else v) for fn,v in fields])
for fn,v in fields:
  if fn in (2,3) and isinstance(v, (bytes,bytearray)):
    sub=parse_protobuf_bytes_fields(v)
    print(' proof', fn, [(a, len(b) if isinstance(b,(bytes,bytearray)) else b) for a,b in sub])
    for a,b in sub:
      if a==1 and isinstance(b,(bytes,bytearray)):
        eid=extid_of(b)
        print('  pubkey len', len(b), 'extid', eid, 'MATCH' if eid==target else '')
        if eid==target:
          Path('/tmp/zeroomega_pubkey.b64').write_text(base64.b64encode(b).decode())
          print('WROTE KEY')
